#include <stdio.h>
#include <math.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 1005
#define INF 1e18

typedef struct {
    double x, y;
} Point;

Point cities[MAXN];
int n;
double r, theta;

double dist[MAXN][MAXN];

double sq(double x) { return x * x; }

double angle_between(Point a, Point b, Point c) {
    // angle between vectors ab and bc
    double abx = b.x - a.x, aby = b.y - a.y;
    double bcx = c.x - b.x, bcy = c.y - b.y;
    double dot = abx * bcx + aby * bcy;
    double norm_ab = sqrt(abx*abx + aby*aby);
    double norm_bc = sqrt(bcx*bcx + bcy*bcy);
    if (norm_ab < 1e-12 || norm_bc < 1e-12) return 0.0;
    double cos_ang = dot / (norm_ab * norm_bc);
    if (cos_ang > 1.0) cos_ang = 1.0;
    if (cos_ang < -1.0) cos_ang = -1.0;
    return acos(cos_ang);
}

double dp[MAXN][MAXN]; // dp[last][prev] = min distance to reach last with prev before it
int carrots[MAXN][MAXN]; // max carrots with that distance

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lf %lf", &cities[i].x, &cities[i].y);
    }
    scanf("%lf %lf", &r, &theta);
    theta = theta * M_PI / 180.0; // convert to radians

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            dist[i][j] = sqrt(sq(cities[i].x - cities[j].x) + sq(cities[i].y - cities[j].y));
        }
    }

    // Initialize
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            dp[i][j] = INF;
            carrots[i][j] = -1;
        }
    }

    // Base: start at city 1, first move to any city j
    for (int j = 1; j <= n; j++) {
        if (j == 1) continue; // can stay? No, moving to new city needed for carrot
        double d = dist[1][j];
        if (d <= r) {
            dp[j][1] = d;
            carrots[j][1] = 2; // visited 1 and j
        }
    }

    int max_carrots = 1; // at least city 1

    // DP over path length
    for (int prev = 1; prev <= n; prev++) {
        for (int last = 1; last <= n; last++) {
            if (dp[last][prev] >= INF) continue;
            int cur_carrots = carrots[last][prev];
            if (cur_carrots > max_carrots) max_carrots = cur_carrots;

            for (int next = 1; next <= n; next++) {
                if (next == last) continue; // must move to a different city
                double new_dist = dp[last][prev] + dist[last][next];
                if (new_dist > r + 1e-12) continue;

                // Check angle condition if we have at least 2 previous points
                double ang = angle_between(cities[prev], cities[last], cities[next]);
                if (ang > theta + 1e-12) continue;

                if (new_dist < dp[next][last] - 1e-12) {
                    dp[next][last] = new_dist;
                    carrots[next][last] = cur_carrots + 1;
                } else if (fabs(new_dist - dp[next][last]) < 1e-12) {
                    if (cur_carrots + 1 > carrots[next][last]) {
                        carrots[next][last] = cur_carrots + 1;
                    }
                }
            }
        }
    }

    printf("%d\n", max_carrots);
    return 0;
}

#include <stdio.h>
#include <math.h>
#include <string.h>

#define MAXN 20
#define MAXK 1000
#define INF 1e18

int n;
double x[MAXN], y[MAXN];
double r, theta;
double dist[MAXN][MAXN];
// dp[k][from][cur] = min distance to have k carrots, at city cur, came from city from
// from = n means starting (no previous direction)
double dp[MAXK+1][MAXN+1][MAXN];

int main(){
    scanf("%d %lf %lf", &n, &r, &theta);
    for(int i=0;i<n;i++) scanf("%lf %lf",&x[i],&y[i]);

    for(int i=0;i<n;i++)
        for(int j=0;j<n;j++)
            dist[i][j]=sqrt((x[i]-x[j])*(x[i]-x[j])+(y[i]-y[j])*(y[i]-y[j]));

    for(int k=0;k<=MAXK;k++)
        for(int f=0;f<=n;f++)
            for(int c=0;c<n;c++) dp[k][f][c]=INF;

    dp[0][n][0]=0.0; // start at city 0 (1-indexed city 1), no previous

    int ans=0;
    for(int k=0;k<MAXK;k++){
        for(int f=0;f<=n;f++){
            for(int c=0;c<n;c++){
                if(dp[k][f][c]>=INF) continue;
                double d=dp[k][f][c];
                for(int nx=0;nx<n;nx++){
                    if(nx==c) continue;
                    // check angle
                    if(f<n){
                        double ax=x[c]-x[f], ay=y[c]-y[f];
                        double bx=x[nx]-x[c], by=y[nx]-y[c];
                        double dot=ax*bx+ay*by;
                        double la=sqrt(ax*ax+ay*ay), lb=sqrt(bx*bx+by*by);
                        double cosA=dot/(la*lb);
                        if(cosA>1) cosA=1; if(cosA<-1) cosA=-1;
                        double angle=acos(cosA);
                        if(angle>theta+1e-9) continue;
                    }
                    double nd=d+dist[c][nx];
                    if(nd<=r+1e-9 && nd<dp[k+1][c][nx]){
                        dp[k+1][c][nx]=nd;
                        if(k+1>ans) ans=k+1;
                    }
                }
            }
        }
    }
    printf("%d\n",ans);
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define INF 1e100
#define EPS 1e-12

typedef struct {
    double x, y;
} Point;

static Point *p;
static int n;
static double R, TH;

/*
State graph:
A state is an oriented edge (a -> b), meaning the rabbit is currently at city b,
and the previous city was a. From this state it may go to c (c != b), provided
the turning angle at b between vectors (b-a) and (c-b) is <= TH.

Each transition adds:
- one carrot (for arriving at c)
- travel cost dist(b,c)

Start:
The rabbit starts at city 1 with no previous direction. So the first move can be
from 1 to any j != 1, costing dist(1,j) and giving 1 carrot.
Also, staying at city 1 gives 0 carrots.

We need the maximum number of carrots with total length <= R.
This is a maximum mean-cycle style problem on a weighted directed graph with
positive edge costs and unit rewards. Let dp[k][state] be minimum cost to obtain
exactly k carrots and end at state. Since number of states is O(n^2), and n is
small enough for cubic preprocessing / dynamic programming in intended tasks.

We use:
dp_next[v] = min over u->v (dp[u] + cost(u,v))
where each transition gains exactly 1 carrot.

Then answer is largest k such that some state has cost <= R, including k=0.

Without explicit constraints in statement, this solution targets moderate n
(around <= 50), with O(n^3 + K * E) where K is answer bound estimated by
minimum positive edge length.
*/

static double dist_pt(int i, int j) {
    double dx = p[i].x - p[j].x;
    double dy = p[i].y - p[j].y;
    return sqrt(dx * dx + dy * dy);
}

int main(void) {
    if (scanf("%d %lf %lf", &n, &R, &TH) != 3) return 0;

    p = (Point*)malloc((n + 1) * sizeof(Point));
    for (int i = 1; i <= n; i++) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    if (n == 1) {
        printf("0\n");
        free(p);
        return 0;
    }

    double **d = (double**)malloc((n + 1) * sizeof(double*));
    for (int i = 0; i <= n; i++) {
        d[i] = (double*)malloc((n + 1) * sizeof(double));
    }

    double minEdge = INF;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (i == j) d[i][j] = 0.0;
            else {
                d[i][j] = dist_pt(i, j);
                if (d[i][j] > EPS && d[i][j] < minEdge) minEdge = d[i][j];
            }
        }
    }

    if (minEdge >= INF / 2 || R + EPS < minEdge) {
        printf("0\n");
        for (int i = 0; i <= n; i++) free(d[i]);
        free(d);
        free(p);
        return 0;
    }

    int S = n * n; /* encode (a,b) as a*n + b, 1-based cities but 0-based state ids */
    int *from = (int*)malloc(S * sizeof(int));
    int *to   = (int*)malloc(S * sizeof(int));

    for (int a = 1; a <= n; a++) {
        for (int b = 1; b <= n; b++) {
            int id = (a - 1) * n + (b - 1);
            from[id] = a;
            to[id] = b;
        }
    }

    /* Build transitions */
    int maxE = S * n;
    int *head = (int*)malloc(S * sizeof(int));
    int *nxt = (int*)malloc(maxE * sizeof(int));
    int *vv = (int*)malloc(maxE * sizeof(int));
    double *w = (double*)malloc(maxE * sizeof(double));
    int ecnt = 0;

    for (int i = 0; i < S; i++) head[i] = -1;

    double cosTH = cos(TH);

    for (int a = 1; a <= n; a++) {
        for (int b = 1; b <= n; b++) {
            if (a == b) continue;
            int u = (a - 1) * n + (b - 1);

            double v1x = p[b].x - p[a].x;
            double v1y = p[b].y - p[a].y;
            double len1 = d[a][b];

            for (int c = 1; c <= n; c++) {
                if (c == b) continue;

                double ok = 1.0;
                if (TH < M_PI - 1e-12) {
                    double v2x = p[c].x - p[b].x;
                    double v2y = p[c].y - p[b].y;
                    double len2 = d[b][c];
                    double cs = (v1x * v2x + v1y * v2y) / (len1 * len2);
                    if (cs > 1.0) cs = 1.0;
                    if (cs < -1.0) cs = -1.0;
                    if (cs + 1e-12 < cosTH) ok = 0.0;
                }
                if (ok > 0.5) {
                    int v = (b - 1) * n + (c - 1);
                    vv[ecnt] = v;
                    w[ecnt] = d[b][c];
                    nxt[ecnt] = head[u];
                    head[u] = ecnt++;
                }
            }
        }
    }

    /* Upper bound on carrots */
    int Kmax = (int)(R / minEdge) + 2;

    double *dp = (double*)malloc(S * sizeof(double));
    double *ndp = (double*)malloc(S * sizeof(double));

    for (int i = 0; i < S; i++) dp[i] = INF;

    int ans = 0;

    /* First move from city 1 to j */
    for (int j = 1; j <= n; j++) {
        if (j == 1) continue;
        int id = (1 - 1) * n + (j - 1);
        dp[id] = d[1][j];
        if (dp[id] <= R + EPS) ans = 1;
    }

    for (int k = 2; k <= Kmax; k++) {
        for (int i = 0; i < S; i++) ndp[i] = INF;

        for (int u = 0; u < S; u++) {
            if (dp[u] >= INF / 2) continue;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = vv[e];
                double cand = dp[u] + w[e];
                if (cand < ndp[v]) ndp[v] = cand;
            }
        }

        double best = INF;
        for (int i = 0; i < S; i++) {
            dp[i] = ndp[i];
            if (dp[i] < best) best = dp[i];
        }

        if (best <= R + EPS) ans = k;
        else break;
    }

    printf("%d\n", ans);

    free(dp);
    free(ndp);
    free(head);
    free(nxt);
    free(vv);
    free(w);
    free(from);
    free(to);
    for (int i = 0; i <= n; i++) free(d[i]);
    free(d);
    free(p);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct City {
    double x, y;
};

double dist(const City& a, const City& b) {
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

double angle(const City& a, const City& b, const City& c) {
    double v1x = b.x - a.x, v1y = b.y - a.y;
    double v2x = c.x - b.x, v2y = c.y - b.y;
    double dot = v1x * v2x + v1y * v2y;
    double norm1 = sqrt(v1x * v1x + v1y * v1y);
    double norm2 = sqrt(v2x * v2x + v2y * v2y);
    if (norm1 == 0 || norm2 == 0) return 0;
    double cos_angle = dot / (norm1 * norm2);
    cos_angle = max(-1.0, min(1.0, cos_angle));
    return acos(cos_angle) * 180.0 / M_PI;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double r, theta;
    cin >> n >> r >> theta;

    vector<City> cities(n);
    for (int i = 0; i < n; i++) {
        cin >> cities[i].x >> cities[i].y;
    }

    // dp[i][j][k] = max carrots ending at city j, coming from city i, 
    // but we'll simplify: dp[pos][dist_idx] with direction tracking
    // Since n ≤ 50 and coordinates are moderate, use double for distance

    // State: (current_city, previous_city, distance_used)
    // We'll use a map for sparse DP
    struct State {
        int curr, prev;
        double dist_used;
        int carrots;
        bool operator<(const State& other) const {
            if (curr != other.curr) return curr < other.curr;
            if (prev != other.prev) return prev < other.prev;
            return dist_used < other.dist_used;
        }
    };

    // Use BFS/DP with priority queue (Dijkstra-like) to maximize carrots
    // dp[curr][prev] = max carrots achievable for a given distance
    // We'll store map from distance to carrots for each (curr, prev)

    vector<vector<map<double, int>>> dp(n, vector<map<double, int>>(n));

    // Initial state: at city 1 (index 0), no previous city
    // For first move, any direction is allowed (no angle constraint)
    priority_queue<pair<double, pair<int, int>>> pq; // (-carrots, (curr, prev))
    // Actually we need max carrots, so use negative

    // Start: we're at city 0 with 0 carrots, no previous direction
    // We'll handle first move separately

    int max_carrots = 1; // Starting city gives 1 carrot

    // Initialize: from city 0 to any city j (including itself)
    for (int j = 0; j < n; j++) {
        double d = dist(cities[0], cities[j]);
        if (d <= r) {
            if (dp[j][0].count(d) == 0 || dp[j][0][d] < 2) {
                dp[j][0][d] = 2; // 1 for start + 1 for arriving at j
                max_carrots = max(max_carrots, 2);
            }
        }
    }

    // DP: for each state, try to extend
    bool changed = true;
    while (changed) {
        changed = false;
        for (int curr = 0; curr < n; curr++) {
            for (int prev = 0; prev < n; prev++) {
                if (dp[curr][prev].empty()) continue;

                auto it = dp[curr][prev].begin();
                while (it != dp[curr][prev].end()) {
                    double dist_used = it->first;
                    int carrots = it->second;

                    // Try going to next city
                    for (int next = 0; next < n; next++) {
                        double d = dist(cities[curr], cities[next]);
                        double new_dist = dist_used + d;
                        if (new_dist > r) continue;

                        // Check angle constraint
                        if (prev != curr) { // We have a previous segment
                            double ang = angle(cities[prev], cities[curr], cities[next]);
                            if (ang > theta) continue;
                        }

                        int new_carrots = carrots + 1;

                        auto& mp = dp[next][curr];
                        bool better = false;
                        // Remove dominated states (higher distance with same or fewer carrots)
                        auto it2 = mp.lower_bound(new_dist);
                        if (it2 != mp.begin()) {
                            auto it3 = prev(it2);
                            if (it3->second >= new_carrots) {
                                // There's a state with less or equal distance and more carrots
                                continue;
                            }
                        }
                        // Remove states that are dominated by this new state
                        auto it3 = mp.lower_bound(new_dist);
                        while (it3 != mp.end() && it3->second <= new_carrots) {
                            it3 = mp.erase(it3);
                        }

                        if (mp.count(new_dist) == 0 || mp[new_dist] < new_carrots) {
                            mp[new_dist] = new_carrots;
                            max_carrots = max(max_carrots, new_carrots);
                            changed = true;
                        }
                    }
                    ++it;
                }
            }
        }
    }

    cout << max_carrots << "\n";

    return 0;
}

