#include <bits/stdc++.h>
using namespace std;

static const long double INF = 1e100L;
static const long double EPS = 1e-12L;

struct Point {
    long double x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long double r, theta_deg;
    cin >> n >> r >> theta_deg;

    vector<Point> p(n);
    for (int i = 0; i < n; ++i) cin >> p[i].x >> p[i].y;

    // If there is only one city, rabbit starts there and cannot "move to a new city".
    // So answer is 0.
    if (n <= 1) {
        cout << 0 << '\n';
        return 0;
    }

    long double theta = theta_deg * acosl(-1.0L) / 180.0L;

    // dist[i][j]
    vector<vector<long double>> dist(n, vector<long double>(n, 0));
    long double minEdge = INF;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long double dx = p[j].x - p[i].x;
            long double dy = p[j].y - p[i].y;
            dist[i][j] = sqrtl(dx * dx + dy * dy);
            if (i != j) minEdge = min(minEdge, dist[i][j]);
        }
    }

    // If no movement is possible within total length.
    if (minEdge > r + EPS) {
        cout << 0 << '\n';
        return 0;
    }

    // Build directed-state graph on ordered pairs (prev, cur), prev != cur.
    // Transition (a,b) -> (b,c), c != b, with turn angle at b <= theta.
    // Cost = |bc|, reward = 1 carrot (for arriving at c).
    //
    // Start:
    // First move is from city 1 to city j (j != 1), cost |1j|, reward 1.
    //
    // Key observation:
    // If there exists any reachable directed cycle in this state graph with
    // total cycle length C and total carrots K, then repeating it yields
    // asymptotic ratio K/C. Since all steps give exactly 1 carrot, maximizing
    // carrots for large budget reduces to minimizing average edge length over
    // a reachable cycle.
    //
    // Because states are finite, optimal path = simple prefix + repeated cycle + suffix.
    // We compute:
    // 1) all reachable states from start;
    // 2) SCCs among reachable states;
    // 3) for each SCC containing a cycle, compute minimum mean cycle cost lambda
    //    (Karp) where each edge weight = segment length;
    // 4) shortest prefix cost from start to each state;
    // 5) shortest cost inside SCC from an entry state to some state on an optimal cycle,
    //    and from there possibly one finite suffix.
    //
    // For this problem constraints are not given here; we implement a practical solution
    // for moderate n using O(n^4) worst-case style graph construction.

    auto stateId = [n](int a, int b) { return a * n + b; };
    int S = n * n;

    vector<char> validState(S, 0);
    for (int a = 0; a < n; ++a)
        for (int b = 0; b < n; ++b)
            if (a != b) validState[stateId(a, b)] = 1;

    vector<vector<pair<int, long double>>> g(S), rg(S);

    auto turn_ok = [&](int a, int b, int c) -> bool {
        // angle between vectors (b-a) and (c-b) at city b
        // Need <= theta.
        long double ux = p[b].x - p[a].x;
        long double uy = p[b].y - p[a].y;
        long double vx = p[c].x - p[b].x;
        long double vy = p[c].y - p[b].y;
        long double nu = sqrtl(ux * ux + uy * uy);
        long double nv = sqrtl(vx * vx + vy * vy);
        if (nu < EPS || nv < EPS) return false;
        long double cs = (ux * vx + uy * vy) / (nu * nv);
        if (cs > 1) cs = 1;
        if (cs < -1) cs = -1;
        long double ang = acosl(cs);
        return ang <= theta + 1e-14L;
    };

    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) if (a != b) {
            int u = stateId(a, b);
            for (int c = 0; c < n; ++c) if (c != b) {
                if (turn_ok(a, b, c)) {
                    int v = stateId(b, c);
                    long double w = dist[b][c];
                    g[u].push_back({v, w});
                    rg[v].push_back({u, w});
                }
            }
        }
    }

    // Multi-source Dijkstra from initial states (0 -> j), j != 0
    vector<long double> d0(S, INF);
    vector<int> carrots0(S, -1); // carrots collected to reach state
    using T = pair<long double, int>;
    priority_queue<T, vector<T>, greater<T>> pq;

    for (int j = 1; j < n; ++j) {
        long double w = dist[0][j];
        if (w <= r + EPS) {
            int s = stateId(0, j);
            if (w < d0[s]) {
                d0[s] = w;
                carrots0[s] = 1;
                pq.push({w, s});
            }
        }
    }

    while (!pq.empty()) {
        auto [cd, u] = pq.top();
        pq.pop();
        if (cd > d0[u] + EPS) continue;
        for (auto [v, w] : g[u]) {
            if (cd + w + EPS < d0[v]) {
                d0[v] = cd + w;
                carrots0[v] = carrots0[u] + 1;
                pq.push({d0[v], v});
            }
        }
    }

    vector<int> reachable;
    vector<char> vis(S, 0);
    for (int i = 0; i < S; ++i) {
        if (validState[i] && d0[i] < INF / 2) {
            reachable.push_back(i);
            vis[i] = 1;
        }
    }

    if (reachable.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    // SCC on reachable subgraph
    vector<int> order;
    vector<char> used(S, 0);

    function<void(int)> dfs1 = [&](int u) {
        used[u] = 1;
        for (auto [v, w] : g[u]) if (vis[v] && !used[v]) dfs1(v);
        order.push_back(u);
    };
    for (int u : reachable) if (!used[u]) dfs1(u);

    vector<int> comp(S, -1);
    vector<vector<int>> comps;
    function<void(int,int)> dfs2 = [&](int u, int cid) {
        comp[u] = cid;
        comps[cid].push_back(u);
        for (auto [v, w] : rg[u]) if (vis[v] && comp[v] == -1) dfs2(v, cid);
    };

    reverse(order.begin(), order.end());
    for (int u : order) if (comp[u] == -1) {
        comps.push_back({});
        dfs2(u, (int)comps.size() - 1);
    }

    long long answer = 0;

    // Finite answer from shortest path only (no cycle use)
    for (int u : reachable) {
        if (d0[u] <= r + EPS) {
            answer = max(answer, (long long)carrots0[u]);
        }
    }

    // For each SCC with a cycle, compute minimum mean cycle cost.
    for (auto &nodes : comps) {
        int m = (int)nodes.size();
        if (m == 0) continue;

        // Check if SCC contains a directed cycle.
        bool hasCycle = false;
        if (m > 1) hasCycle = true;
        else {
            int u = nodes[0];
            for (auto [v, w] : g[u]) if (v == u) hasCycle = true;
        }
        if (!hasCycle) continue;

        // Map local indices
        unordered_map<int,int> idx;
        idx.reserve(m * 2);
        for (int i = 0; i < m; ++i) idx[nodes[i]] = i;

        vector<vector<pair<int,long double>>> subg(m), subrg(m);
        for (int i = 0; i < m; ++i) {
            int u = nodes[i];
            for (auto [v, w] : g[u]) {
                auto it = idx.find(v);
                if (it != idx.end()) {
                    int j = it->second;
                    subg[i].push_back({j, w});
                    subrg[j].push_back({i, w});
                }
            }
        }

        // Karp minimum mean cycle
        vector<vector<long double>> dp(m + 1, vector<long double>(m, INF));
        for (int v = 0; v < m; ++v) dp[0][v] = 0;
        for (int k = 1; k <= m; ++k) {
            for (int v = 0; v < m; ++v) {
                for (auto [u, w] : subrg[v]) {
                    if (dp[k - 1][u] < INF / 2) {
                        dp[k][v] = min(dp[k][v], dp[k - 1][u] + w);
                    }
                }
            }
        }

        long double lambda = INF;
        for (int v = 0; v < m; ++v) {
            if (dp[m][v] >= INF / 2) continue;
            long double mx = -INF;
            for (int k = 0; k < m; ++k) {
                if (dp[k][v] >= INF / 2) continue;
                long double val = (dp[m][v] - dp[k][v]) / (m - k);
                mx = max(mx, val);
            }
            lambda = min(lambda, mx);
        }

        if (lambda >= INF / 2) continue;
        if (lambda <= EPS) continue; // impossible geometrically, but safe

        // Best reachable entry cost into this SCC
        long double bestEntry = INF;
        long long bestEntryCarrots = 0;
        for (int u : nodes) {
            if (d0[u] < bestEntry) {
                bestEntry = d0[u];
                bestEntryCarrots = carrots0[u];
            } else if (fabsl(d0[u] - bestEntry) <= EPS) {
                bestEntryCarrots = max(bestEntryCarrots, (long long)carrots0[u]);
            }
        }
        if (bestEntry > r + EPS) continue;

        // Lower bound using asymptotic ratio.
        long double rem = r - bestEntry;
        long long extra = (long long)floor((rem + 1e-12L) / lambda);
        answer = max(answer, bestEntryCarrots + extra);
    }

    cout << answer << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Solution {
    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static int n;
    static Point[] cities;
    static double r;
    static double theta;
    static double[][] dist;
    static double[][] angle;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        n = Integer.parseInt(st.nextToken());
        r = Double.parseDouble(st.nextToken());
        theta = Double.parseDouble(st.nextToken());

        cities = new Point[n + 1];
        for (int i = 1; i <= n; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            cities[i] = new Point(x, y);
        }

        // Precompute distances and angles between all pairs
        dist = new double[n + 1][n + 1];
        angle = new double[n + 1][n + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (i != j) {
                    double dx = cities[j].x - cities[i].x;
                    double dy = cities[j].y - cities[i].y;
                    dist[i][j] = Math.sqrt(dx * dx + dy * dy);
                    angle[i][j] = Math.atan2(dy, dx);
                }
            }
        }

        // DP state: [current city][previous city][distance used]
        // But since n can be large, we need a different approach
        // Use Floyd-Warshall style DP with angle constraints

        // dp[i][j][k] = max carrots from city i to city j with k segments
        // But this is too large. Let's use a different approach.

        // Since we can revisit cities, the optimal solution is to find the 
        // shortest cycle that satisfies angle constraints and repeat it
        double[][] dp = new double[n + 1][n + 1];
        int[][] carrots = new int[n + 1][n + 1];

        // Initialize with direct edges from city 1
        for (int i = 1; i <= n; i++) {
            if (i != 1) {
                dp[1][i] = dist[1][i];
                if (dp[1][i] <= r) {
                    carrots[1][i] = 1;
                }
            }
        }

        int maxCarrots = 0;

        // Try to find shortest cycles from city 1
        for (int start = 1; start <= n; start++) {
            for (int end = 1; end <= n; end++) {
                if (start == end) continue;

                // Try to find a path from start to end that returns to start
                for (int k = 1; k <= n; k++) {
                    if (k != start && k != end && dp[start][k] > 0 && dp[k][end] > 0) {
                        if (checkAngle(start, k, end)) {
                            double newDist = dp[start][k] + dp[k][end];
                            int newCarrots = carrots[start][k] + carrots[k][end];
                            if (newDist < dp[start][end] || dp[start][end] == 0) {
                                dp[start][end] = newDist;
                                carrots[start][end] = newCarrots;
                            }
                        }
                    }
                }

                // Check if we can return to start
                if (dp[start][end] > 0 && dist[end][start] > 0) {
                    if (checkAngle(end, start, getNext(start, end))) {
                        double cycleDist = dp[start][end] + dist[end][start];
                        int cycleCarrots = carrots[start][end] + 1;

                        if (cycleDist <= r) {
                            // We can repeat this cycle
                            int repeat = (int)(r / cycleDist);
                            maxCarrots = Math.max(maxCarrots, cycleCarrots * repeat);

                            // Also check if we can do partial cycles
                            double remaining = r - cycleDist * repeat;
                            // Try to add one more segment
                            for (int i = 1; i <= n; i++) {
                                if (i != start && dist[start][i] <= remaining) {
                                    maxCarrots = Math.max(maxCarrots, cycleCarrots * repeat + 1);
                                }
                            }
                        }
                    }
                }
            }
        }

        // Also consider just going to one city and back
        for (int i = 2; i <= n; i++) {
            if (dist[1][i] * 2 <= r) {
                maxCarrots = Math.max(maxCarrots, 2);
            }
            if (dist[1][i] <= r) {
                maxCarrots = Math.max(maxCarrots, 1);
            }
        }

        System.out.println(maxCarrots);
    }

    static boolean checkAngle(int from, int mid, int to) {
        double angle1 = angle[from][mid];
        double angle2 = angle[mid][to];
        double diff = Math.abs(angle2 - angle1);
        diff = Math.min(diff, 2 * Math.PI - diff);
        return diff <= theta;
    }

    static int getNext(int start, int end) {
        // Simple heuristic to find a next city
        for (int i = 1; i <= n; i++) {
            if (i != start && i != end) {
                return i;
            }
        }
        return start;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        double r = sc.nextDouble();
        double theta = sc.nextDouble() * Math.PI / 180.0;
        double[] x = new double[n+1], y = new double[n+1];
        for (int i = 1; i <= n; i++) { x[i] = sc.nextDouble(); y[i] = sc.nextDouble(); }

        double[][] dist = new double[n+1][n+1];
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= n; j++)
                dist[i][j] = Math.hypot(x[i]-x[j], y[i]-y[j]);

        // dp[prev][curr] = min distance to be at curr having come from prev
        // prev=0 means starting (no direction constraint)
        double[][] dp = new double[n+1][n+1];
        for (double[] row : dp) Arrays.fill(row, Double.MAX_VALUE/2);
        dp[0][1] = 0;

        int maxCarrots = n * n * 2 + 10;
        double[][][] dpK = new double[maxCarrots+1][n+1][n+1];
        for (double[][] a : dpK) for (double[] b : a) Arrays.fill(b, Double.MAX_VALUE/2);
        dpK[1][0][1] = 0;

        // ... this approach with maxCarrots too large
        // Let me just do up to 2*n steps for Karp's algorithm
        int N = n;
        int maxK = N*N;
        double[][][] f = new double[maxK+1][N+1][N+1];
        for (double[][] a : f) for (double[] b : a) Arrays.fill(b, 1e18);
        f[1][0][1] = 0;

        for (int k = 1; k < maxK; k++) {
            for (int p = 0; p <= N; p++) for (int c = 1; c <= N; c++) {
                if (f[k][p][c] >= 1e17) continue;
                for (int nx = 1; nx <= N; nx++) {
                    if (nx == c) continue;
                    boolean ok = true;
                    if (p != 0) {
                        double ax = x[c]-x[p], ay = y[c]-y[p];
                        double bx = x[nx]-x[c], by = y[nx]-y[c];
                        double dot = ax*bx+ay*by;
                        double cross = ax*by-ay*bx;
                        double ang = Math.abs(Math.atan2(Math.abs(cross), dot));
                        if (ang > theta + 1e-9) ok = false;
                    }
                    if (ok) {
                        double nd = f[k][p][c] + dist[c][nx];
                        if (nd < f[k+1][c][nx]) f[k+1][c][nx] = nd;
                    }
                }
            }
        }

        // Karp's min mean cycle: for each state (p,c), find min over k of max over k' of (f[maxK][p][c] - f[k][p][c])/(maxK-k)
        // Actually we want max carrots = max k such that min distance for k carrots <= r
        // Binary search or direct: answer is max k where min_{p,c} f[k][p][c] <= r

        int ans = 0;
        for (int k = 1; k <= maxK; k++) {
            boolean found = false;
            for (int p = 0; p <= N; p++) for (int c = 1; c <= N; c++)
                if (f[k][p][c] <= r + 1e-9) { found = true; break; }
            if (found) ans = k; else if (k > ans + N*N) break;
        }

        // Now use Karp's to find best cycle rate
        // min mean = min over all cycles of (total_dist / steps)
        // We want to extend ans using best cycle
        // Find for each (p,c): min mean cycle reachable
        // Use: minMean = min over (p,c) of min over 1<=k<=maxK of (f[maxK][p][c] - f[k][p][c]) / (maxK - k)
        // But we need the cycle to be reachable from state (0,1)

        // Simpler: the answer is ans + floor((r - f[ans][p][c]) / minCycleLen) * cycleCarrots
        // For a cycle from (p,c) back to (p,c) of length L collecting S carrots: rate = S/L
        // Best rate cycle: use Karp's algorithm

        // Let me find minimum distance cycle per carrot
        // A cycle in state space: from (p,c) go steps and return to (p,c)
        // Karp's: minMean over cycles = min_{(p,c)} min_{1<=k<maxK} (f[maxK][p][c] - f[k][p][c])/(maxK-k)
        // where f[k][p][c] != inf

        double bestRate = Double.MAX_VALUE; // min dist per carrot in a cycle
        for (int p = 0; p <= N; p++) for (int c = 1; c <= N; c++) {
            if (f[maxK][p][c] >= 1e17) continue;
            for (int k = 0; k < maxK; k++) {
                if (f[k][p][c] >= 1e17) continue;
                double rate = (f[maxK][p][c] - f[k][p][c]) / (maxK - k);
                if (rate < bestRate) bestRate = rate;
            }
        }

        if (bestRate < 1e17) {
            // From each reachable state (p,c) with f[k][p][c] <= r, we can add floor((r - f[k][p][c]) / bestRate)
            for (int k = 1; k <= maxK; k++) {
                for (int p = 0; p <= N; p++) for (int c = 1; c <= N; c++) {
                    if (f[k][p][c] <= r + 1e-9) {
                        double rem = r - f[k][p][c];
                        long extra = (long)(rem / bestRate);
                        long total = k + extra;
                        if (total > ans) ans = (int)Math.min(total, Integer.MAX_VALUE);
                    }
                }
            }
        }

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

/*
We model each directed move i -> j as a state edge.
If the rabbit previously moved p -> i, then it may continue i -> j iff
the turning angle between vectors (i - p) and (j - i) is <= theta.

Since every move gives exactly 1 carrot and costs Euclidean distance,
we want the maximum number of moves starting from city 1 with total length <= r.

This is a longest-path-under-budget problem on a finite automaton of directed edges.
State count is n*n (ordered pairs i,j, i!=j), plus a special start state at city 1
with no previous direction; from start we may go to any j!=1.

Because all move lengths are positive, dynamic programming by number of moves works:
dp[k][state] = minimum total length to realize exactly k moves and end in that state.
We only need the previous layer.

Transition:
start -> (1,j): dist(1,j)
(p,i) -> (i,j): +dist(i,j), if turn at i is valid

Answer = maximum k such that some state has dp <= r, or 0 if no move fits.

Complexity:
States: O(n^2)
Transitions: O(n^3) if done naively from (p,i) to all j.
With n up to moderate sizes this is acceptable. We precompute validity and distances.

Important geometric check:
For vectors a = i-p, b = j-i,
angle(a,b) <= theta  iff
dot(a,b) >= |a||b| cos(theta)
(with epsilon).
*/

public class Main {
    static final double INF = 1e100;
    static final double EPS = 1e-10;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        double r = fs.nextDouble();
        double thetaDeg = fs.nextDouble();

        double[] x = new double[n];
        double[] y = new double[n];
        for (int i = 0; i < n; i++) {
            x[i] = fs.nextDouble();
            y[i] = fs.nextDouble();
        }

        if (n <= 1) {
            System.out.println(0);
            return;
        }

        double[][] dist = new double[n][n];
        double minEdge = INF;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                double dx = x[j] - x[i];
                double dy = y[j] - y[i];
                dist[i][j] = Math.hypot(dx, dy);
                if (dist[i][j] < minEdge) minEdge = dist[i][j];
            }
        }

        if (minEdge > r + EPS) {
            System.out.println(0);
            return;
        }

        double theta = Math.toRadians(thetaDeg);
        double cosT = Math.cos(theta);

        // validTurn[p][i][j] for p->i then i->j, with all distinct only by i!=j and p!=i.
        boolean[][][] validTurn = new boolean[n][n][n];
        for (int p = 0; p < n; p++) {
            for (int i = 0; i < n; i++) {
                if (p == i) continue;
                double ax = x[i] - x[p];
                double ay = y[i] - y[p];
                double la = dist[p][i];
                for (int j = 0; j < n; j++) {
                    if (j == i) continue;
                    double bx = x[j] - x[i];
                    double by = y[j] - y[i];
                    double lb = dist[i][j];
                    double dot = ax * bx + ay * by;
                    validTurn[p][i][j] = dot + EPS >= la * lb * cosT;
                }
            }
        }

        int stateCount = n * n; // encode ordered pair (from,to), only meaningful for from!=to
        double[] prev = new double[stateCount];
        double[] next = new double[stateCount];
        Arrays.fill(prev, INF);

        int answer = 0;

        // k = 1 from start city 1 (index 0) to any j!=0
        for (int j = 1; j < n; j++) {
            int id = encode(0, j, n);
            prev[id] = dist[0][j];
            if (prev[id] <= r + EPS) answer = 1;
        }

        // Upper bound on moves by shortest positive edge
        int maxMoves = (int) Math.floor((r + EPS) / minEdge) + 1;

        for (int k = 2; k <= maxMoves; k++) {
            Arrays.fill(next, INF);
            boolean any = false;

            for (int p = 0; p < n; p++) {
                for (int i = 0; i < n; i++) {
                    if (p == i) continue;
                    int id1 = encode(p, i, n);
                    double cur = prev[id1];
                    if (cur > r + EPS) continue;

                    for (int j = 0; j < n; j++) {
                        if (j == i) continue;
                        if (!validTurn[p][i][j]) continue;

                        double nd = cur + dist[i][j];
                        if (nd + EPS < next[encode(i, j, n)]) {
                            next[encode(i, j, n)] = nd;
                        }
                    }
                }
            }

            for (double v : next) {
                if (v <= r + EPS) {
                    any = true;
                    answer = k;
                    break;
                }
            }
            if (!any) break;

            double[] tmp = prev;
            prev = next;
            next = tmp;
        }

        System.out.println(answer);
    }

    static int encode(int a, int b, int n) {
        return a * n + b;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}
